  if (ui->nav_state.active && !ui->nav_active_latched)
    {
      qiban_ui_set_page(ui, 1, LV_ANIM_ON);
    }

  ui->nav_active_latched = ui->nav_state.active;

  ui->tick++;
  qiban_ui_refresh_labels(ui);
}

