  if (ret < 0)
    {
      return ret;
    }

  if (requested_pcm_path != NULL && *requested_pcm_path != '\0')
    {
      snprintf(pcm_path, sizeof(pcm_path), "%s", requested_pcm_path);
    }

  snprintf(start_cmd, sizeof(start_cmd),
