          return EXIT_FAILURE;
        }

      result.action = QIBAN_VOICE_ACTION_NAVIGATE;
      snprintf(result.target, sizeof(result.target), "%s", text);
      ret = qiban_execute_result(text, &result);
      return ret < 0 ? EXIT_FAILURE : OK;
