    {
      ret = qiban_poll_server_job("asr", argc >= 3 ? argv[2] : NULL);
      return ret < 0 ? EXIT_FAILURE : OK;
    }

  if (strcmp(argv[1], "mock-asr") == 0)
    {
      if (qiban_join_args(argc, argv, 2, text, sizeof(text)) < 0)
        {
          qiban_usage(argv[0]);
          return EXIT_FAILURE;
        }

      ret = qiban_handle_mock_asr(text);
      return ret < 0 ? EXIT_FAILURE : OK;
