static void qiban_ui_update_alerts(struct qiban_ui_s *ui)
{
  char alert_text[128];
  lv_color_t color;

  if (ui->state.alert_overspeed)
    {
      snprintf(alert_text, sizeof(alert_text), "Alert: Slow down");
      color = lv_color_hex(0xb91c1c);
    }
  else if (ui->state.alert_low_battery)
    {
      snprintf(alert_text, sizeof(alert_text), "Alert: Charge soon");
      color = lv_color_hex(0xb45309);
    }
  else if (ui->state.alert_fatigue)
    {
      snprintf(alert_text, sizeof(alert_text), "Alert: Take a break");
      color = lv_color_hex(0x1d4ed8);
    }
  else if (ui->nav_state.active)
    {
      snprintf(alert_text, sizeof(alert_text), "Nav: %s",
               ui->nav_state.destination[0] != '\0' ?
               ui->nav_state.destination : "Route active");
      color = lv_color_hex(0x1d4ed8);
    }
  else
    {
      snprintf(alert_text, sizeof(alert_text), "Status: Ride stable");
      color = lv_color_hex(0x166534);
    }

  lv_obj_set_style_bg_color(ui->alert_panel, color, 0);
  lv_label_set_text(ui->alert_label, alert_text);
}

static void qiban_ui_build_map_status(struct qiban_ui_s *ui,
                                      char *buffer, size_t buffer_size)
{
  if (ui->nav_state.active)
    {
      snprintf(buffer, buffer_size, "%s | %s | %s | ETA %d min",
               ui->nav_state.destination[0] != '\0' ?
               ui->nav_state.destination : "导航中",
               ui->nav_state.status[0] != '\0' ?
               ui->nav_state.status : "路线进行中",
               ui->nav_state.next_turn[0] != '\0' ?
               ui->nav_state.next_turn : "等待下一条导航指令",
               ui->nav_state.eta_minutes);
      return;
    }

  if (ui->map_state.ready)
    {
      snprintf(buffer, buffer_size, "%s",
               ui->map_state.title[0] != '\0' ? ui->map_state.title : "Map");
    }
  else
    {
      snprintf(buffer, buffer_size, "%s",
               ui->map_state.status[0] != '\0' ?
               ui->map_state.status : "Waiting for map");
    }
}

static void qiban_ui_refresh_map(struct qiban_ui_s *ui)
{
  char map_status[160];

  qiban_ui_build_map_status(ui, map_status, sizeof(map_status));

  if (ui->map_state.ready)
    {
      if (strcmp(ui->active_map_path, ui->map_state.image_path) != 0 ||
          ui->active_map_updated_at != ui->map_state.updated_at)
        {
          lv_image_cache_drop(ui->map_state.image_path);
          lv_image_set_src(ui->map_page_image, ui->map_state.image_path);
          snprintf(ui->active_map_path, sizeof(ui->active_map_path), "%s",
                   ui->map_state.image_path);
          ui->active_map_updated_at = ui->map_state.updated_at;
        }

      lv_obj_clear_flag(ui->map_page_image, LV_OBJ_FLAG_HIDDEN);
      lv_obj_add_flag(ui->map_page_placeholder, LV_OBJ_FLAG_HIDDEN);
      lv_obj_clear_flag(ui->map_page_status_label, LV_OBJ_FLAG_HIDDEN);
      lv_label_set_text(ui->map_page_status_label, map_status);
    }
  else
    {
      ui->active_map_path[0] = '\0';
      ui->active_map_updated_at = 0;
      lv_obj_add_flag(ui->map_page_image, LV_OBJ_FLAG_HIDDEN);
      lv_obj_clear_flag(ui->map_page_placeholder, LV_OBJ_FLAG_HIDDEN);
      lv_obj_add_flag(ui->map_page_status_label, LV_OBJ_FLAG_HIDDEN);
      lv_label_set_text(ui->map_page_placeholder, map_status);
    }
}

static lv_coord_t qiban_ui_clamp_coord(lv_coord_t value, lv_coord_t min_value,
                                       lv_coord_t max_value)
{
  if (value < min_value)
    {
      return min_value;
    }

  if (value > max_value)
    {
      return max_value;
    }

  return value;
}

static void qiban_ui_refresh_location_marker(struct qiban_ui_s *ui)
{
  double min_lon;
  double max_lon;
  double min_lat;
  double max_lat;
  double lon_span;
  double lat_span;
  double x_ratio;
  double y_ratio;
  lv_coord_t width;
  lv_coord_t height;
  lv_coord_t usable_width;
  lv_coord_t usable_height;
  lv_coord_t x;
  lv_coord_t y;

  if (ui->location_marker == NULL || ui->map_frame == NULL)
    {
      return;
    }

  if (!ui->nav_state.active || !ui->location_state.valid)
    {
      lv_obj_add_flag(ui->location_marker, LV_OBJ_FLAG_HIDDEN);
      if (ui->location_label != NULL)
        {
          lv_obj_add_flag(ui->location_label, LV_OBJ_FLAG_HIDDEN);
        }
      return;
    }

  width = lv_obj_get_width(ui->map_frame);
  height = lv_obj_get_height(ui->map_frame);
  usable_width = width - (QIBAN_MAP_MARKER_PAD * 2);
  usable_height = height - (QIBAN_MAP_MARKER_PAD * 2);
  if (usable_width <= 0 || usable_height <= 0)
    {
      return;
    }

  min_lon = ui->nav_state.start_longitude < ui->nav_state.end_longitude ?
            ui->nav_state.start_longitude : ui->nav_state.end_longitude;
  max_lon = ui->nav_state.start_longitude > ui->nav_state.end_longitude ?
            ui->nav_state.start_longitude : ui->nav_state.end_longitude;
  min_lat = ui->nav_state.start_latitude < ui->nav_state.end_latitude ?
            ui->nav_state.start_latitude : ui->nav_state.end_latitude;
  max_lat = ui->nav_state.start_latitude > ui->nav_state.end_latitude ?
            ui->nav_state.start_latitude : ui->nav_state.end_latitude;

  lon_span = max_lon - min_lon;
  lat_span = max_lat - min_lat;
  if (lon_span < 0.000001)
    {
      lon_span = 0.000001;
    }

  if (lat_span < 0.000001)
    {
      lat_span = 0.000001;
    }

  x_ratio = (ui->location_state.longitude - min_lon) / lon_span;
  y_ratio = (max_lat - ui->location_state.latitude) / lat_span;
  if (x_ratio < 0.0)
    {
      x_ratio = 0.0;
    }
  else if (x_ratio > 1.0)
    {
      x_ratio = 1.0;
    }

  if (y_ratio < 0.0)
    {
      y_ratio = 0.0;
    }
  else if (y_ratio > 1.0)
    {
      y_ratio = 1.0;
    }

  x = QIBAN_MAP_MARKER_PAD +
      (lv_coord_t)(x_ratio * usable_width) - QIBAN_MAP_MARKER_SIZE / 2;
  y = QIBAN_MAP_MARKER_PAD +
      (lv_coord_t)(y_ratio * usable_height) - QIBAN_MAP_MARKER_SIZE / 2;
  x = qiban_ui_clamp_coord(x, 0, width - QIBAN_MAP_MARKER_SIZE);
  y = qiban_ui_clamp_coord(y, 0, height - QIBAN_MAP_MARKER_SIZE);

  lv_obj_set_pos(ui->location_marker, x, y);
  lv_obj_clear_flag(ui->location_marker, LV_OBJ_FLAG_HIDDEN);
  lv_obj_move_foreground(ui->location_marker);

  if (ui->location_label != NULL)
    {
      lv_label_set_text_fmt(ui->location_label, "ME %.5f, %.5f",
                            ui->location_state.longitude,
                            ui->location_state.latitude);
      lv_obj_align_to(ui->location_label, ui->location_marker,
                      LV_ALIGN_OUT_TOP_LEFT, -4, -4);
      lv_obj_clear_flag(ui->location_label, LV_OBJ_FLAG_HIDDEN);
      lv_obj_move_foreground(ui->location_label);
    }
}

static void qiban_ui_refresh_labels(struct qiban_ui_s *ui)
